from heapq import heappop, heappush


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)

    graph: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    inf = 10**18
    pi = [inf] * m
    pi[0] = 0
    for u in range(m):
        pu = pi[u]
        for v, cap, cost, _ in graph[u]:
            if cap > 0 and pu + cost < pi[v]:
                pi[v] = pu + cost

    total_cost = 0
    for _ in range(k):
        dist = [inf] * m
        dist[0] = 0
        prev_node = [-1] * m
        prev_edge = [-1] * m
        pq = [(0, 0)]

        while pq:
            d, u = heappop(pq)
            if d != dist[u]:
                continue
            pu = pi[u]
            for ei, (v, cap, cost, _) in enumerate(graph[u]):
                if cap > 0:
                    nd = d + cost + pu - pi[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        prev_node[v] = u
                        prev_edge[v] = ei
                        heappush(pq, (nd, v))

        if dist[m - 1] == inf:
            break

        for i in range(m):
            if dist[i] < inf:
                pi[i] += dist[i]

        v = m - 1
        while v != 0:
            u = prev_node[v]
            ei = prev_edge[v]
            edge = graph[u][ei]
            edge[1] -= 1
            graph[v][edge[3]][1] += 1
            total_cost += edge[2]
            v = u

    return -total_cost
